<?php
declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';$pageTitle='Work Planner';
$filter=(string)($_GET['filter']??'All');if(!in_array($filter,['All','To do','In progress','Done'],true))$filter='All';
$search=trim((string)($_GET['q']??''));$where=[];$params=[];if($filter!=='All'){$where[]='status=?';$params[]=$filter;}if($search!==''){$where[]='(title LIKE ? OR category LIKE ? OR description LIKE ?)';array_push($params,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}
$sql='SELECT * FROM work_items'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY FIELD(status,\'In progress\',\'To do\',\'Done\'), FIELD(priority,\'High\',\'Medium\',\'Low\'), due_date IS NULL, due_date ASC, created_at DESC';$q=$pdo->prepare($sql);$q->execute($params);$items=$q->fetchAll();$stats=$pdo->query("SELECT COUNT(*) total, SUM(status='To do') todo, SUM(status='In progress') doing, SUM(status='Done') done FROM work_items")->fetch();
$coverFiles = glob(__DIR__ . '/../uploads/cover/cover.{jpg,jpeg,png,webp}', GLOB_BRACE) ?: [];
$workCoverUrl = $coverFiles ? '../uploads/cover/' . basename($coverFiles[0]) : '';
require __DIR__.'/../includes/header.php';
