<?php if(!$items): ?><div class="empty-state"><div class="empty-icon">▤</div><h3>No work items found</h3><p>Add your first task or adjust the filter.</p></div><?php else: ?><div class="work-list"><?php foreach($items as $it): ?><article class="work-card"><div class="work-card-top"><span class="status-pill status-<?= e(strtolower(str_replace(' ','-',$it['status']))) ?>"><?= e($it['status']) ?></span><span class="priority-pill priority-<?= e(strtolower($it['priority'])) ?>"><?= e($it['priority']) ?> priority</span></div><h3><?= e($it['title']) ?></h3><div class="work-meta"><span><?= e($it['category']) ?></span><?php if($it['due_date']): ?><span>Due <?= e(date('d M Y',strtotime($it['due_date']))) ?></span><?php endif; ?><?php if($it['start_date']): ?><span>Started <?= e(date('d M Y',strtotime($it['start_date']))) ?></span><?php endif; ?></div><?php if($it['description']): ?><p class="work-description"><?= nl2br(e($it['description'])) ?></p><?php endif; ?><div class="work-card-actions"><form action="<?= e(app_url('actions/work-status.php')) ?>" method="post" class="status-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><label class="sr-only" for="workstatus<?= (int)$it['id'] ?>">Status</label><select id="workstatus<?= (int)$it['id'] ?>" name="status" onchange="this.form.submit()"><?php foreach(['To do','In progress','Done'] as $st): ?><option <?= $it['status']===$st?'selected':'' ?>><?= e($st) ?></option><?php endforeach; ?></select><noscript><button class="btn btn-outline" type="submit">Update</button></noscript></form><details class="inline-edit"><summary>Edit</summary><form action="<?= e(app_url('actions/work-save.php')) ?>" method="post" class="form-stack"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><label>Title<input name="title" value="<?= e($it['title']) ?>" maxlength="160" required></label><label>Description<textarea name="description" rows="3" maxlength="5000"><?= e((string)$it['description']) ?></textarea></label><div class="form-row"><label>Category<input name="category" value="<?= e($it['category']) ?>" maxlength="60" required></label><label>Priority<select name="priority"><?php foreach(['Low','Medium','High'] as $v): ?><option <?= $it['priority']===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></label></div><div class="form-row"><label>Status<select name="status"><?php foreach(['To do','In progress','Done'] as $v): ?><option <?= $it['status']===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach; ?></select></label><label>Start date<input type="date" name="start_date" value="<?= e((string)$it['start_date']) ?>"></label></div><label>Due date<input type="date" name="due_date" value="<?= e((string)$it['due_date']) ?>"></label><button class="btn btn-gold" type="submit">Save changes</button></form></details><form action="<?= e(app_url('actions/work-remove.php')) ?>" method="post" data-confirm="Remove this work item?" class="inline-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><button class="btn btn-outline danger-action" type="submit">Remove</button></form></div></article><?php endforeach; ?></div><?php endif; ?></section>
